```python
import threading

class SafeCounter:
    def __init__(self):
        self._value = 0
        self._lock = threading.Lock()
    def increment(self, n=1):
        with self._lock:
            self._value += n
    def decrement(self, n=1):
        with self._lock:
            self._value -= n
    def value(self):
        with self._lock:
            return self._value
```
